sparql_response:
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?paternalGrandmother ?grandmotherLabel WHERE {
  dbr:Edward_Harley,_4th_Earl_of_Oxford_and_Earl_Mortimer dbo:parent ?father .
  ?father dbp:mother ?paternalGrandmother .
  OPTIONAL {
    ?paternalGrandmother rdfs:label ?grandmotherLabel .
    FILTER (lang(?grandmotherLabel) = "en")
  }
}
LIMIT 100

